        if (edgeDirNDC.x < 0.0 || (abs(edgeDirNDC.x) < 0.001 && edgeDirNDC.y < 0.0)) {
            edgeDirNDC = -edgeDirNDC;
        }

        edgeDirNDC = normalize(edgeDirNDC);
